!function(){"use strict";var e=window.IWACVis;e&&e.addTranslations&&(e.addTranslations("en",{"Loading press language metrics":"Loading press language metrics","lexical.mean_readability":"Mean readability (Flesch)","lexical.mean_richness":"Mean lexical richness","lexical.mean_words":"Mean words per article","lexical.readability_title":"Readability over time","lexical.readability_desc":"Mean Flesch reading-ease score (French adaptation) of the articles published each year, computed from the OCR text. Higher = easier to read.","lexical.richness_title":"Lexical richness over time","lexical.richness_desc":"Mean MATTR (moving-average type-token ratio, 50-word window) of the articles published each year, computed from the OCR text. Higher = more varied vocabulary. Unlike a plain type-token ratio, MATTR does not fall as articles get longer, so long and short articles are directly comparable; articles under 50 words are left unscored.","lexical.words_title":"Article length over time","lexical.words_desc":"Mean number of words per article published each year, counted from the OCR text.","lexical.np_read_title":"Newspapers by readability","lexical.np_read_desc":"Newspapers with at least {min} articles, ranked by mean Flesch reading-ease score computed from the OCR text (top {top}). Higher = easier to read.","lexical.np_rich_title":"Newspapers by lexical richness","lexical.np_rich_desc":"Newspapers with at least {min} articles, ranked by mean MATTR (moving-average type-token ratio, 50-word window) computed from the OCR text (top {top}). Higher = more varied vocabulary.","lexical.axis_readability":"Flesch score","lexical.axis_richness":"MATTR"}),e.addTranslations("fr",{"Loading press language metrics":"Chargement des indicateurs de langue","lexical.mean_readability":"Lisibilité moyenne (Flesch)","lexical.mean_richness":"Richesse lexicale moyenne","lexical.mean_words":"Mots par article (moyenne)","lexical.readability_title":"Lisibilité au fil du temps","lexical.readability_desc":"Score moyen de lisibilité Flesch (adaptation française) des articles publiés chaque année, calculé à partir du texte océrisé. Plus le score est élevé, plus le texte est facile à lire.","lexical.richness_title":"Richesse lexicale au fil du temps","lexical.richness_desc":"MATTR moyen (ratio types-occurrences en moyenne glissante, fenêtre de 50 mots) des articles publiés chaque année, calculé à partir du texte océrisé. Plus la valeur est élevée, plus le vocabulaire est varié. Contrairement à un ratio types-occurrences simple, le MATTR ne diminue pas avec la longueur du texte : articles longs et courts sont donc directement comparables. Les articles de moins de 50 mots ne sont pas notés.","lexical.words_title":"Longueur des articles au fil du temps","lexical.words_desc":"Nombre moyen de mots par article publié chaque année, compté à partir du texte océrisé.","lexical.np_read_title":"Journaux par lisibilité","lexical.np_read_desc":"Journaux comptant au moins {min} articles, classés par score moyen de lisibilité Flesch calculé à partir du texte océrisé (top {top}). Plus le score est élevé, plus le texte est facile à lire.","lexical.np_rich_title":"Journaux par richesse lexicale","lexical.np_rich_desc":"Journaux comptant au moins {min} articles, classés par MATTR moyen (ratio types-occurrences en moyenne glissante, fenêtre de 50 mots) calculé à partir du texte océrisé (top {top}). Plus la valeur est élevée, plus le vocabulaire est varié.","lexical.axis_readability":"Score Flesch","lexical.axis_richness":"MATTR"}))}();